-- DB-side audit assertions. Unique procedure fixture commits, raw DML rolls back.
SOURCE tests/procedures/support/fixture.sql;
START TRANSACTION;
SET @w=(SELECT COALESCE(MAX(audit_id),0) FROM Audit_Log);
INSERT INTO Loans(customer_id,principal_amount,interest_rate,tenure_months,status,disbursed_date) VALUES(@p3_c1,100,1,12,'Active',CURDATE());
SET @loan=LAST_INSERT_ID();
UPDATE Loans SET status='Closed' WHERE loan_id=@loan;
DELETE FROM Loans WHERE loan_id=@loan;
SET @n=(SELECT COUNT(*) FROM Audit_Log WHERE audit_id>@w AND table_name='Loans' AND record_pk=CAST(@loan AS CHAR));
CALL bank_lab.sp_assert_equal(DATABASE(),'EXP17 direct loan INSERT UPDATE DELETE count','3',@n);
SET @ok=(SELECT COUNT(*)=3 AND COUNT(DISTINCT action_type)=3 FROM Audit_Log WHERE audit_id>@w AND table_name='Loans' AND record_pk=CAST(@loan AS CHAR) AND db_session_user=USER() AND actor_type='System' AND actor_employee_id IS NULL AND actor_customer_id IS NULL AND ((action_type='INSERT' AND old_value IS NULL AND JSON_UNQUOTE(JSON_EXTRACT(new_value,'$.status'))='Active') OR (action_type='UPDATE' AND JSON_UNQUOTE(JSON_EXTRACT(old_value,'$.status'))='Active' AND JSON_UNQUOTE(JSON_EXTRACT(new_value,'$.status'))='Closed') OR (action_type='DELETE' AND new_value IS NULL AND JSON_UNQUOTE(JSON_EXTRACT(old_value,'$.status'))='Closed')));
CALL bank_lab.sp_assert_true(DATABASE(),'EXP17 direct loan JSON and actor',@ok,'All three mutation snapshots and System attribution');
SET @before=(SELECT balance FROM Accounts WHERE account_id=@p3_a);
UPDATE Accounts SET balance=balance+1 WHERE account_id=@p3_a;
SET @ok=(SELECT COUNT(*)=1 FROM Audit_Log WHERE audit_id>@w AND table_name='Accounts' AND record_pk=CAST(@p3_a AS CHAR) AND action_type='UPDATE' AND JSON_EXTRACT(old_value,'$.balance')=CAST(@before AS JSON) AND JSON_EXTRACT(new_value,'$.balance')=CAST(@before+1 AS JSON) AND JSON_UNQUOTE(JSON_EXTRACT(old_value,'$.status'))='Active' AND JSON_UNQUOTE(JSON_EXTRACT(new_value,'$.status'))='Active' AND db_session_user=USER() AND actor_type='System');
CALL bank_lab.sp_assert_true(DATABASE(),'EXP17 direct account balance JSON',@ok,'DBA +1 produces one exact before/after snapshot');
INSERT INTO Transactions(account_id,transaction_type,amount,balance_after,channel,status,reference_no) SELECT @p3_a,'Deposit',1,balance,'Online','Completed',fn_generate_reference() FROM Accounts WHERE account_id=@p3_a;
SET @tx=LAST_INSERT_ID();
SET @ok=(SELECT COUNT(*)=1 FROM Audit_Log WHERE audit_id>@w AND table_name='Transactions' AND record_pk=CAST(@tx AS CHAR) AND action_type='INSERT' AND old_value IS NULL AND JSON_EXTRACT(new_value,'$.balance_after')=CAST(@before+1 AS JSON) AND JSON_UNQUOTE(JSON_EXTRACT(new_value,'$.status'))='Completed' AND db_session_user=USER() AND actor_type='System');
CALL bank_lab.sp_assert_true(DATABASE(),'EXP17 direct transaction JSON',@ok,'DBA direct deposit audited');
SET @n=(SELECT COALESCE(MAX(audit_id),0) FROM Audit_Log);
CALL bank_lab.sp_expect_error(DATABASE(),'EXP17 guard rejected no mutation','UPDATE {db}.Accounts SET balance=1 WHERE account_id=@p3_a',5015);
SET @actual=(SELECT COALESCE(MAX(audit_id),0) FROM Audit_Log);
CALL bank_lab.sp_assert_equal(DATABASE(),'EXP17 rejected statement creates zero audit rows',@n,@actual);
CALL bank_lab.sp_expect_error(DATABASE(),'EXP17 audit UPDATE immutable','UPDATE {db}.Audit_Log SET table_name=table_name WHERE audit_id=@n',5013);
CALL bank_lab.sp_expect_error(DATABASE(),'EXP17 audit DELETE immutable','DELETE FROM {db}.Audit_Log WHERE audit_id=@n',5013);
SET @n=(SELECT COUNT(*) FROM Audit_Log WHERE audit_id>@w);
CALL bank_lab.sp_assert_equal(DATABASE(),'EXP17 DBA total audit delta','5',@n);
SELECT CONCAT('AUDIT_COUNT|',table_name,'|',action_type,'|',COUNT(*)) FROM Audit_Log WHERE audit_id>@w GROUP BY table_name,action_type ORDER BY table_name,action_type;
SELECT CONCAT('AUDIT_JSON|',JSON_OBJECT('audit_id',audit_id,'table_name',table_name,'action_type',action_type,'db_session_user',db_session_user,'actor_type',actor_type,'old_value',old_value,'new_value',new_value)) FROM Audit_Log WHERE audit_id>@w ORDER BY audit_id;
ROLLBACK;
